Helpmenu = {Open = false, Helpmarker = {}}

local Texts = {
	["DE"] = {
		["Accounts und Charaktere"] = "Nach der Erstellung eines Accounts und eines Charakters startest du in Zone 11 — einer Region, die zu Dillimores Hoffnung gehört, einer Kolonie, die dich gerettet und aufgenommen hat.\nNach einem kurzen Tutorial, das die grundlegenden Spielmechaniken erklärt, kannst du deine Abenteuer beginnen und die Welt von San Andreas erkunden.\n\nEmpfehlungssystem\nBei der Registrierung kannst du den Namen eines Rekrutierers angeben.\nDer Rekrutierer erhält Belohnungen, sobald der geworbene Spieler eine bestimmte Anzahl an Spielstunden erreicht hat.\nGeworbene Spieler können im Selbstmenü (/me) eingesehen werden.\n\nCharaktereinstellungen (F5)\nDrücke F5, um die Charaktereinstellungen zu öffnen. Hier kannst du:\n\nDie Introsequenz überspringen\nAutomatisches Einloggen aktivieren\nEinen Lieblingscharakter für das automatische Einloggen auswählen\nDein Passwort ändern\nDeine Sprache ändern\nDeinen Spawnpunkt ändern\nBonus-Codes eingeben\n\nRegeln & Sanktionen\nEs gibt ein Regelwerk.\nVerstöße können zu Sanktionen gegen den Account führen, die je nach Schwere temporäre oder permanente Sperren sein können.\n\nSpawnpunkte\nDu kannst zwischen folgenden Spawnorten wählen:\n\nDillimore (Sichere Zone)\nCrazy Joe’s Farm\nBlueberry (Sichere Zone)\nAdam Turners Hütte (im Wald)\nBigfoot Club",
		["Spielerwelt"] = "Welt & Zonen\nDie Karte ist in 24 Zonen unterteilt.\nEinige dieser Zonen erfordern den Survivor Pass und dessen Upgrades für den Zugang.\n\nFunkmasten\nJede Zone enthält einen Funkmast, der wichtige Orte in dieser Zone aufdeckt.\n\nWildtiere & Jagd\nTiere streifen durch die Welt.\nSobald du das Jagdmesser freigeschaltet hast, kannst du Tiere töten, um zu sammeln:\n\nFell\nFleisch\nAndere Ressourcen\n\nDekorative NPCs\nDekorative NPCs können angeklickt werden, um Erfahrungspunkte zu erhalten.\n\nInteraktive Charaktere\nIm Spiel findest du dutzende Charaktere.\n\nDrücke Leertaste zum Sprechen\nDrücke E zum Interagieren\nBitte um Hilfe oder schenke Geschenke\nGeschenke erhöhen Freundschaftsstufen\n\nEntdeckbare Orte\nEs gibt entdeckbare Orte, die als sichere Zonen dienen.\nNach der Entdeckung werden sie auf deiner Karte sichtbar.\n\nUnterkünfte\nKaufe Unterkünfte, um neue Spawnpunkte zu setzen.\n\nShops & Händler\nDie Welt bietet verschiedene Läden:\n\nWeste-Shop\nBars\nCoupon-Shop\nFischerladen\nEssensstände (Hotdog-Stände, Snack-/Getränkeautomaten, Wasserspender)\nItem-Shop\nSchlüsselladen\nFahrzeughandel\nWaffenladen\nSaatgutladen\nKleidungsladen",
		["Zombies"] = "Außerhalb der sicheren Schutzgebiete herrscht Chaos. Zombies streifen frei durch die Straßen — töte sie, bevor sie dich töten, und hilf, San Andreas von der Infektion zurückzuerobern.\n\nJeder getötete Zombie belohnt dich mit:\n\nErfahrungspunkte – Steige im Level auf und schalte mächtige Spielmechaniken frei\nGeld – Gib es für wichtige und luxuriöse Dinge aus\nGehirnmasse – Eine seltene Ressource, die für das Überleben notwendig ist\nNutze Geld und Gehirnmasse, um zu erwerben:\n\nWaffen\nFahrzeuge\nSchlüssel\nUnterkünfte\n...und vieles mehr!\nBeide Ressourcen sind entscheidend für Überleben und Fortschritt in dieser postapokalyptischen Welt.\nWirst du aufsteigen und das Land säubern — oder Teil der Horde werden?",
		["Aktivitäten"] = "Berufe\nDurchsuche das Meer nach Schätzen und Muscheln als Schatzjäger.\nSammle Steine, Erze und Diamanten als Höhlenforscher.\nSammle Holz und verarbeite oder verkaufe es als Holzfäller.\nSammle Müll mit einem Straßenkehrer.\nSammle Müll im Meer als Ozeanreiniger.\nSuche mit einem Metalldetektor nach Schätzen als Schatzsucher.\nHilf beim Abschleppen von Fahrzeugen als Mechanikerhelfer.\nPflege Gräber als Friedhofswärter.\n\nAngeln\nBesuche einen Angelshop, finde einen Ort, der dir gefällt, und versuche dein Glück beim Fischen und Sammeln von Muscheln. Fische können verkauft, gekocht und gegessen oder in ein Aquarium gesetzt werden, wo sie Erfahrungspunkte generieren.\n\nFahrzeugmissionen\nAn Polizeistationen, Krankenhäusern und Feuerwachen findest du spezielle Fahrzeuge, die bei Betreten Missionen starten. Die Art der Mission hängt vom Fahrzeug ab – ob Polizeiauto, Krankenwagen oder Feuerwehrauto.\nIn ganz San Andreas begegnen dir verschiedene Notfallsituationen. Deine Aufgabe ist es, entsprechend zu reagieren: Verletzte Überlebende retten, bei Notfällen helfen oder Bedrohungen bewältigen.\nÜberlebende oder Missionsziele werden bei Interaktion in dein Fahrzeug geladen.\nFür jede erfolgreiche Aktion erhältst du Erfahrungspunkte.\nWenn du die Mission abbrichst, bekommst du dennoch Teilbelohnungen basierend auf deinem Fortschritt.\nBei korrekter Missionsabgabe (z. B. Überlebende abliefern) gibt es mehr XP, Geld und Fertigkeitspunkte.\n\nNester\nSind überall in San Andreas zu finden.\nKönnen mit Dynamit zerstört werden.\nNach Zerstörung stürmen Zombies heraus.\nZombies aus Nestern geben Bonus-XP.\n\nAirdrop-Versorgungen\nVersorgungsabwürfe landen alle 15 Minuten an zufälligen Orten, nachdem sie eingesammelt wurden.\nEnthalten viele Items.\nSind auf der Karte mit einem Blip markiert.\n\nInfizierte Überlebende\nInfizierte Überlebende spawnen überall in San Andreas.\nDu kannst mit einer Spritze eine Blutprobe von lebenden Infizierten nehmen.\nDas Töten bringt Geld.\nRespawnzeit: 5 Minuten.\n\nLoot-Aktivitäten\nVerlassene Fahrzeuge\nSind überall auf der Karte verteilt.\nStarten ein 15-Sekunden-Minispiel (klicke so viele Items wie möglich).\nMehr Klicks = mehr Beute.\n15-Minuten Cooldown (pro Spieler).\nFahrzeuganzeige: Weiß = lootbar, Rot = Cooldown.\n\nLootbare Häuser\nBenötigen einen Brecheisen zum Betreten.\nSind 15 Minuten nach Öffnung lootbar.\n30-Minuten Cooldown (global).\nChance auf Zombies.\nDurchsuche Innenräume nach Items.\n\nDurchsuchbare Mülleimer\nSind überall in San Andreas verteilt.\nKlicke zum Durchsuchen.\n5-Minuten Cooldown (pro Mülleimer).\nKönnen nützliche Gegenstände enthalten.\nMarkierungssystem wie bei Fahrzeugen.\n\nLootbare Gebäude\nÄhnlich wie lootbare Häuser.\nBenötigen mehr Brecheisen.\nDurchsuche Kisten innen nach Items.\nEin exklusiver Gegenstand pro Gebäudetyp.\nAlle Objekte durchsuchen = Bonus.\nChance auf Zombies.\n\nBesondere Gebäudefunktionen\nPolizeiwache - Beweismittelkeller\nTöte Zombie mit Schlüsselkarte ODER benutze Dynamit.\nPolizeiwache - Gefängniszellen\nFinde Schlüsselkarte oder benutze Dynamit.\nPolizeiwache & Feuerwache\nEnthalten Dokumente.\n\nLootbare Garagen\nWerden mit Dynamit aufgesprengt.\nBleiben 15 Minuten offen.\nCooldown: 30 Minuten.\nKönnen Beute oder ein demontierbares Fahrzeug enthalten.\n\nBosskämpfe\nKlicke hier für Bosskämpfe\n\nLoot-Serien\nErhalte Bonus-Fertigkeitspunkte für das Plündern mehrerer Dinge innerhalb eines Zeitlimits:\nTyp - Zeitlimit\nMülleimer - 1 Minute\nHaus - 5 Minuten\nFahrzeug - 2 Minuten\nGebäude - 15 Minuten\nAb Serie 3 erhältst du Bonus-Fertigkeitspunkte.\n\nLootbare Gebäudetypen\nGebäudetyp - Exklusiver Gegenstand\nSexshop / Stripclub - Dildo\nTankstelle - Schraubenschlüssel\nWaffenladen - Waffenteile\nKrankenhaus - Verband\nPizzeria - Pizza\nKleidungsladen - Stoff\nSupermarkt - Süßigkeiten\nCluckin’ Bell - Hähnchenkeule\nBurger Shot - Burger\nFeuerwache - Feuerwehrhelm\nPolizeistation - Polizeimütze\nBar - Wein\nFriseursalon - Schere\nDonut-Laden - Donut\nTattoo-Studio - Tätowierfarbe\n\nSchützenarena\nIn der Schützenarena kämpfen Spieler gegeneinander, während sie einen Infernus fahren.\nDein Fahrzeug ist mit Waffen ausgerüstet, sodass du während der Fahrt schießen kannst.\nZiel ist es, andere Spieler durch Rammen und Beschießen aus der Arena zu werfen.\nNach Zerstörung respawnst du automatisch ohne Strafe.\n\nRennarena\nDie Rennarena ermöglicht es dir, gegen andere Spieler in schnellen Fahrzeugrennen anzutreten.\nDie Strecken sind eng und beinhalten viele Kurven.\nJeder Platz erhält Belohnungen entsprechend seiner Position.\n\nKampfarena\nIn der Kampfarena treten Spieler in direkter Nahkampfkonfrontation gegeneinander an.\nVerschiedene Waffen und Kampfmechaniken stehen zur Verfügung.\nDie Arenen sind übersichtlich und bieten zahlreiche taktische Möglichkeiten.\n\nAndere Aktivitäten\nEs gibt eine Vielzahl an weiteren Aktivitäten, die deinen Spielfortschritt unterstützen und für Abwechslung sorgen.",
		["Bosskämpfe"] = "Bigfoot\nNach dem ersten Töten von Bigfoot und dem Abschluss der zugehörigen Quest erhältst du Zugang zu mächtigen neuen Features:\n\nAlle 4 Stunden kannst du ein Minigun mit begrenzter Munition einsammeln.\nDu erhältst den Standort des Bigfoot Clubs, der Folgendes beinhaltet:\nDas Bigfoot-Gefängnis\nDas Bigfoot-Clubhaus\nNachdem du 25 Bigfoot-Köpfe im Gefängnis abgegeben hast, erhältst du den Schlüssel zum Clubhaus.\n\nIm Clubhaus:\n\nDu schaltest den Spawnpunkt - Bigfoot Club frei.\nDu kannst wiederholt 25 Bigfoot-Köpfe abgeben für:\nErfahrungspunkte\nEinen Safe-Schlüssel\nEine zufällige Item-Kiste\nZusätzlich generiert der gefangene Bigfoot passiv Erfahrungspunkte, solange du online bist und Mitglied des Clubs bist.",
		["Fahrzeuge"] = "Fahrzeuge kannst du über Shops, Händler oder als Questbelohnung erhalten.\nEin freier Fahrzeugslot ist erforderlich, um ein Fahrzeug zu kaufen oder zu bekommen.\n\nFahrzeugslots\nWerden von bestimmten NPCs vergeben.\nZusätzliche Slots über eine Fähigkeit.\nServer-Garage\nFahrzeuge werden standardmäßig in der Server-Garage gespeichert.\nZugänglich von allen Kolonie-Basen.\nFahrzeuge werden beim Einloggen automatisch geladen.\n\nSteuerung\nAktion - Taste\nMotor an/aus - X\nLicht an/aus - L\nFahrzeuge benötigen Kraftstoff (gefunden beim Looten oder an Tankstellen).\n\nInteraktionsmenü\nKlicke auf ein Fahrzeug, um:\nInfos anzusehen\nUmparken\nZugang zum Kofferraum\n\nZufällige Fahrzeughändler\nBieten einzigartige Fahrzeuge an, die nicht in Shops erhältlich sind:\nCheetah\nMoonbeam\nEsperanto\nBobcat\nBJ Injection\nBanshee\nHotknife\nCaddy\nHermes\nWalton\nBurrito\n\nIndividualisierung & Tuning\nTuning-Garagen: Fahrzeuge mit Teilen & Geld aufrüsten.\nMechaniker: Baut leistungsstarke Motoren ein (höhere Höchstgeschwindigkeit).\nPay ‘N Sprays: Fahrzeugfarbe ändern.\n\nPrivate Garagen\nKaufbare Garagen existieren in der Welt.\nBenutze /mg, um das Tor zu öffnen/schließen, wenn du Besitzer bist.",
		["Systeme"] = "Spieler-Interaktion\nKlicke auf einen anderen Spieler, um das Interaktionsmenü zu öffnen.\nHier kannst du Items geben und Freundschaftsanfragen senden.\n\nPartys\nErstelle eine temporäre Party, um mit anderen zusammen Zombies zu besiegen.\nZombie-Kills von Partymitgliedern in der Nähe gewähren Bonus-Erfahrungspunkte.\n\nChatsystem\nNachrichten mit /s [Text] (Schrei) und /m [Text] (Megafon) haben größere Reichweite.\n\nBestenliste\nEine Top-10-Liste zeigt die besten Spieler in verschiedenen Kategorien.\n\nWirtschaft\nGeld kann sicher in Safes aufbewahrt werden.\nAlle 4 Stunden kannst du kostenlos am Glücksrad drehen und wertvolle Items, Fahrzeuge u.v.m. gewinnen.\nJede volle Spielstunde erhältst du einen Payday mit Geld und Erfahrung, abhängig von deinem Level. Zudem bekommst du mit jedem Payday eine SAA-Münze.\n\nWaffensystem\nWaffen werden im Inventar gespeichert.\n\nWaffen erhältst du über:\nShops\nQuests\nCrafting\nEs gibt Waffenboxen zur Aufbewahrung von Waffen.\n\nEine Fähigkeit erhöht, wie viele Waffen du tragen kannst.\n\nIm Schießstand kannst du Waffen trainieren, um deine Fähigkeiten zu verbessern.\n\nFähigkeiten\nEs gibt ein Sprint-Level, das beim Laufen steigt. Je höher dein Sprint-Level, desto länger kannst du ununterbrochen sprinten.\nIn San Andreas findest du Skill-Basen mit verschiedenen Fähigkeiten und Vorteilen.\nFähigkeiten kosten Skill-Punkte, die du durch Aktivitäten verdienst.\nVerfügbare Fähigkeiten:\nMedic\nMechaniker\nWaffenexperte\nFahrzeugspezialist\n\nBergbau\nWährend der Bergbau-Aktivität kannst du Erze sammeln.\nErze werden im Ofen zu Barren geschmolzen.\nDiese Barren werden zum Crafting verwendet.\n\nPlatzierbare Objekte\nPlatzierbare Objekte können gekauft oder gecraftet und in der Welt platziert werden:\nSafe\nLagerfeuer (zur Heilung)\nSchwarzes Brett (mit eigenem Text)\nWaffenbox\nWasserspender\n\nFarm-System\nIm Saatgut-Shop kannst du Samen kaufen und pflanzen.\nFolgendes kann gepflanzt werden:\nApfelbäume\nOrangenbäume\nHanf\nKakteen\n\nSpieler-Markt\nKaufe einen Marktstand, um Items zum Verkauf anzubieten.\nAndere Spieler können diese Items direkt an deinem Stand kaufen.\n\nErfahrungs- & Level-System\nDu kannst Erfahrung durch verschiedene Aktivitäten sammeln.\nErfahrung ermöglicht dir, Level aufzusteigen und neue Spielinhalte freizuschalten.\nBenötigte XP für Levelaufstieg:\n250 × (dein Level + 1) + ((dein Level + 1) × 25)\nBeim Levelaufstieg werden dir freigeschaltete Features angezeigt.\nDein Level bestimmt auch deinen Rang.\n\nRänge\nEs gibt 16 Ränge von Anfänger bis Legende.\nMit jedem Rang erhältst du den Standort eines speziellen Ortes.\n\nHilfemenü\nDrücke F1, um das Hilfemenü im Spiel zu öffnen.\n\nCrafting-Menü\nDas Crafting-Menü ist ab Level 25 im Inventar verfügbar.\nCrafting-Rezepte erhältst du im Spielverlauf.\n\nAFK-System\nNach 5 Minuten Inaktivität wirst du automatisch in den AFK-Modus versetzt.\n\nServer-Events & Boni\nEin voller Tag auf San Andreas Apocalypse dauert 4 echte Stunden.\nAlle 15 Minuten erscheint eine Chatbox mit Server-Infos und gewährt Bonus-Erfahrungspunkte.\nDie stündliche Payday gewährt Erfahrung, sofern mindestens ein Generator läuft.\nBei aktivem doppelten XP-Bonus kann die Erfahrung bis zu x4 mit einem Coupon erhöht werden.\nJeden Morgen findet ein Script-Neustart statt.\nNatürliche Ereignisse (z.B. Erdbeben) können das Gameplay beeinflussen.",
		["Kolonien"] = "Kolonie-System\nDu kannst deine eigene Kolonie gründen.\n\nKolonien schalten zusätzliche Spielmechaniken frei und ermöglichen Teamspiel.\n\nKolonien haben ein Levelsystem:\n\nZombie-Kills bringen Erfahrung für die Kolonie.\nErfahrung für das nächste Level:\n2500 × (aktuelles Kolonie-Level + 1) + ((aktuelles Kolonie-Level + 1) × 25)\nKolonien starten mit 5 Spieler- und 1 Fahrzeugslot.\nAlle 5 Level erhält die Kolonie +1 Spieler- und +1 Fahrzeugslot.\nDrücke F7, um das Kolonie-Menü zu öffnen, wo du Mitglieder verwalten und Infos sehen kannst.\n\nMüllverdichter\nNach Freischaltung können Mitglieder Items in den Müllverdichter legen.\nIst dieser voll, kannst du ihn verdichten, was Belohnungen für Mitglied und Kolonie bringt und einen Müllblock erzeugt.\n\nLagerhäuser\nJe höher das Kolonie-Level, desto mehr Lagerhäuser können gekauft werden.\nLagerhäuser speichern Items und Fahrzeuge.\n\nZombie-Experimente\nFühre Experimente an Zombies durch, um mehr über das Virus zu erfahren.\n\nTägliche & Wöchentliche Aufgaben\nSchließe kolonieweite Aufgaben ab und erhalte Spezialbelohnungen.\n\nLaborkämpfe\nZerstöre und erobere feindliche Labore im Kampf mit anderen Kolonien.\nLabore sind farblich auf der Karte nach Koloniebesitz markiert.\n\nLagerhauslieferungen\nLieferungen zu Kolonien und anderen Orten auf der Karte.\n\nGeldtransporter\nFinde verlassene Geldtransporter in San Andreas.\nBelade sie mit Bargeld und liefere sie zum Kolonie-Shelter.\n\nFlaggenjagd\nNach dem täglichen Script-Neustart wird ein zufälliges Shelter gewählt, an dem eine Flagge spawnt.\nKolonien können die Flagge erobern und zum eigenen Shelter bringen für Boni.\n\nShelter\nShelter können zu Kolonie-Sheltern umgewandelt werden und sind dann für alle Mitglieder zugänglich.",
		["NPCs"] = "/",
		["Sammelobjekte"] = "F2 – Persönliche Übersicht\nUnter F2 findest du eine Übersicht über:\n\nErfolge\nDokumente\nStatus-Effekte\nFotos\nCrafting-Rezepte\nEntdeckte Orte\nBekannte Charaktere\n\nDokumente\nDokumente findest du in der Spielwelt.\nSie enthalten:\n\nHintergrundgeschichten von Charakteren\nTipps und Tricks\nWichtige Hinweise\n\nStatus-Effekte\nFreigeschaltete Status-Effekte können ausgewählt werden.\nSie werden unter dem Spielernamen angezeigt und gewähren Vorteile.\n\nFotos & Crafting-Rezepte\nFotos und Rezepte kannst du finden oder verdienen.\n\nBekannte Charaktere\nWenn du einen Charakter getroffen hast, erscheint Hintergrundinfo im F2-Menü.\n\nEntdeckte Orte\nEntdeckte Orte werden mit sicherer Zone auf der Karte angezeigt.\n\nCollectibles\nFinde und sammle Items in der Welt:\n\nHufeisen\nGTA III Logos\nTiki-Statuen\nVersteckte Pakete\nDiese können im Bonus-Shop verwendet werden.\n\nEs gibt weitere Collectibles in Quests, wie:\n\nRostige Kettensägen\nPolizeimarken\nSchlagstöcke\n...und viele mehr.",
		["Changelogs"] = "/",
	}, 
	["EN"] = {
		["Accounts and Characters"] = "After creating an account and a character, you will begin in Zone 11 — a region belonging to Dillimore’s Hope, a colony that rescued and took you in.\nFollowing a short tutorial introducing the basic game mechanics, you are free to start your adventure and explore the world of San Andreas.\n\nReferral System\nWhen registering, you can enter a recruiter's name.\nThe recruiter will receive rewards once the referred player reaches a certain number of play hours.\nReferred players can be viewed via the Self Menu (/me).\n\nCharacter Settings (F5)\nPress F5 to open the character settings. Here you can:\n\nSkip the intro\nEnable automatic account login\nSelect a favorite character for auto-login\nChange your password\nChange your language\nChange your spawn point\nEnter bonus codes\n\nRules & Sanctions\nA rulebook is in place.\nViolations may lead to account sanctions, which can be temporary or permanent bans depending on the severity.\n\nSpawn Points\nYou can choose between the following spawn locations:\n\nDillimore (Safe Zone)\nCrazy Joe’s Farm\nBlueberry (Safe Zone)\nAdam Turner's Cabin (in the woods)\nBigfoot Club",
		["Player World"] = "World & Zones\nThe map is divided into 24 zones.\nSome of these zones require the Survivor Pass and its upgrades to access.\n\nRadio Towers\nEach zone contains a radio tower that reveals key locations in that zone.\n\nWildlife & Hunting\nAnimals roam the world.\nOnce you’ve unlocked the hunting knife, you can kill animals to gather:\n\nFur\nMeat\nOther resources\n\nDecorative NPCs\nDecorative NPCs can be clicked to earn experience points.\n\nInteractive Characters\nYou’ll find dozens of characters throughout the world.\n\nPress Spacebar to talk\nPress E to interact\nAsk for help or give gifts\nGifts increase friendship levels\n\nDiscoverable Locations\nThere are discoverable locations that act as safe zones.\nOnce discovered, they become visible on your map.\n\nShelters\nBuy shelters to set new spawn points.\n\nShops & Vendors\nThe world includes a variety of shops:\n\nVest Shop\nBars\nCoupon Shop\nFisherman’s Store\nFood Vendors (Hot Dog stands, Snack/Drink machines, Water dispensers)\nItem Shop\nKey Store\nVehicle Dealership\nWeapon Store\nSeed Shop\nClothes Shop",
		["Zombies"] = "Outside the safety of protected zones, chaos reigns. Zombies roam the streets freely — kill them before they kill you and help reclaim San Andreas from the infection.\n\nEach zombie you eliminate rewards you with:\n\nExperience Points – Level up and unlock powerful gameplay mechanics\nMoney – Spend it on essentials and luxuries\nBrain Mass – A rare resource needed for survival\nUse money and brain mass to acquire:\n\nWeapons\nVehicles\nKeys\nShelters\n...and much more!\nBoth resources are crucial for survival and progression in this post-apocalyptic world.\nWill you rise and cleanse the land — or become part of the horde?",
		["Activities"] = "Jobs\nSearch the sea for treasures and shells as a Treasure Hunter.\nCollect stones, ores, and diamonds as a Cave Explorer.\nCollect wood and process or sell it as a Lumberjack.\nCollect trash using a sweeper as a Street Cleaner.\nCollect trash in the sea as an Ocean Cleaner.\nSearch for treasures with a metal detector as a Treasure Seeker.\nAssist in towing vehicles as a Mechanic Helper.\nMaintain graves as a Grave Keeper.\nFishing\nVisit a fishing shop, find a spot you like, and try your luck at catching fish and also collect shells. Fish can be sold, cooked and eaten, or placed in an aquarium where they generate experience points.\n\nVehicle Missions\nAt police stations, hospitals, and fire departments, you can find special vehicles that start missions when entered. The type of mission depends on the vehicle — whether it's a police car, ambulance, or fire truck.\nThroughout San Andreas, you’ll encounter different emergency situations. Your task is to respond accordingly: rescue injured survivors, assist in emergencies, or handle threats.\nSurvivors or mission-related targets will be loaded into your vehicle upon interaction.\nYou earn experience points for each successful action.\nIf you abandon the mission, you'll still receive partial rewards based on progress.\nProperly completing missions (e.g., delivering survivors) grants more XP, money, and skill points.\n\nNests\nFound all over San Andreas.\nCan be destroyed using dynamite.\nOnce destroyed, zombies rush out.\nZombies from nests give bonus XP.\n\nAirdrop Supplies\nSupply drops land at random locations every 15 minutes after being collected.\nContain a large number of items.\nMarked on the map with a Blip.\n\nInfected Survivors\nInfected survivors spawn all across San Andreas.\nYou can take a blood sample from a living infected survivor using a syringe.\nKilling them drops money.\nRespawn time: 5 minutes.\n\nLooting Activities\nAbandoned Vehicles\nFound all across the map.\nInitiates a 15-second minigame (click as many items as possible).\nMore clicks = more loot.\n15-minute cooldown (per player).\nVehicle indicator: white = lootable, red = cooldown.\n\nLootable Houses\nRequire a crowbar to enter.\nLootable for 15 minutes after being opened.\n30-minute cooldown (global).\nChance of zombies appearing.\nSearch interiors for items.\n\nSearchable Trash Bins\nFound throughout San Andreas.\nClick to search.\n5-minute cooldown (per bin).\nCan contain useful items.\nMarker system like vehicles.\n\nLootable Buildings\nSimilar to lootable houses.\nRequire more crowbars.\nSearch crates inside for items.\nOne exclusive item per building type.\nLoot all objects = bonus.\nChance of zombies spawning.\n\nSpecial Building Features\nPolice Department - Evidence Room\nKill zombie with keycard OR use dynamite.\nPolice Department - Prison Cells\nFind keycard or use dynamite.\nPolice Department & Fire Station\nContains documents.\n\nLootable Garages\nBlown open using dynamite.\nStay open for 15 minutes.\nCooldown: 30 minutes.\nMay contain loot or a dismantlable vehicle.\n\nBossfights\nClick here for Bossfights\n\nLooting Streaks\nEarn bonus skill points for looting multiple things within a time limit:\nType - Time Limit\nTrash Bin - 1 minute\nHouse - 5 minutes\nVehicle - 2 minutes\nBuilding - 15 minutes\nFrom streak 3 onward, you earn bonus skill points.\n\nLootable Building Types\nBuilding Type - Exclusive Item\nSex Shop / Strip Club - Dildo\nGas Station - Wrench\nGun Store - Weapon Parts\nHospital - Bandage\nPizzeria - Pizza\nClothing Store - Fabric\nSupermarket - Candy\nCluckin’ Bell - Chicken Leg\nBurger Shot - Burger\nFire Station - Firefighter Hat\nPolice Station - Police Cap\nBar - Wine\nHair Salon - Scissors\nDonut Shop - Donut\nTattoo Studio - Tattoo Ink\n\nShooter Arena\nIn the Shooter Arena, players battle each other while driving an Infernus.\nYour vehicle is equipped with vehicle weapons, allowing you to shoot while driving.\nThe goal is to eliminate other players by ramming and shooting them off the arena.\nYou respawn automatically after being destroyed, with no penalties.\n\nRace Arena\nThe Race Arena lets you compete against other players in fast-paced vehicle races.\nTracks are set up across San Andreas with checkpoints and laps.\nAll players start at the same time, and the race begins after a short countdown.",
		["Boss Fights"] = "Bigfoot\nAfter killing Bigfoot for the first time and completing the associated quest, you gain access to powerful new features:\n\nYou can collect a Minigun with limited ammo every 4 hours\nYou receive the location of the Bigfoot Club, which includes:\nThe Bigfoot Prison\nThe Bigfoot Clubhouse\nAfter turning in 25 Bigfoot heads at the prison, you receive the key to the Clubhouse.\n\nInside the Clubhouse:\n\nYou unlock the spawn point - Bigfoot Club\nYou can repeatedly turn in 25 Bigfoot heads for:\nExperience Points\nA Safe Key\nA Random Item Crate\nAdditionally, the captured Bigfoot passively generates experience points while you're online, provided you’re a member of the club.",
		["Vehicles"] = "You can acquire vehicles via shops, dealers, or as quest rewards.\nA free vehicle slot is required to buy or receive a vehicle.\n\nVehicle Slots\nGranted by specific NPCs.\nAdditional slots via a skill.\nServer Garage\nVehicles are stored in the server garage by default.\nAccessible from all colony bases.\nVehicles are loaded automatically on login.\n\nControls\nAction - Key\nToggle engine - X\nToggle lights - L\nVehicles require fuel (found while looting or at gas stations).\n\nInteraction Menu\nClick on a vehicle to:\nView info\nRepark\nAccess trunk\n\nRandom Vehicle Dealers\nOffer unique vehicles not found in shops:\nCheetah\nMoonbeam\nEsperanto\nBobcat\nBJ Injection\nBanshee\nHotknife\nCaddy\nHermes\nWalton\nBurrito\n\nCustomization & Tuning\nTuning garages: Upgrade vehicles with parts & money.\nMechanic: Installs performance engines (higher top speed).\nPay ‘N Sprays: Change vehicle color.\n\nPrivate Garages\nBuyable garages exist in the world.\nUse /mg to open/close the gate if you own it.",
		["Systems"] = "Player Interaction\nClicking on another player opens the player interaction menu.\nHere you can give items to other players and send friend requests.\n\nParties\nCreate a temporary party to team up with others and defeat zombies together.\nZombie kills by party members in close proximity grant bonus experience points.\n\nChat System\nMessages sent with /s [text] (shout) and /m [text] (megaphone) have increased range.\n\nLeaderboard\nA top 10 leaderboard displays the best players in various categories.\n\nEconomy\nMoney can be safely stored in safes.\nEvery 4 hours, you can spin a wheel of fortune for free, winning valuable items, vehicles, and more.\nEvery full in-game hour you receive a payday with money and experience points, depending on your level. Additionally, you receive a SAA Coin with each payday.\n\nWeapon System\nWeapons are stored in your inventory.\n\nWeapons can be obtained via:\nShops\nQuests\nCrafting\nThere are weapon boxes to store weapons.\n\nA skill exists that increases how many weapons you can store.\n\nIn the Shooting Range, you can train weapons to improve your weapon skills.\n\nSkills\nThere is a sprint level that increases as you run. The higher your sprint level, the longer you can run continuously.\nIn San Andreas, you can find skill bases offering various skills for benefits.\nSkills cost skill points earned through activities.\nAvailable Skills:\nMedic\nMechanic\nWeapon Expert\nVehicle Expert\n\nMining\nDuring the mining activity, you can collect ores.\nOres can be smelted in a furnace into bars.\nThese bars can be used to craft items.\n\nPlaceable Objects\nPlaceable objects can be bought or crafted, and placed in the world:\nSafe\nCampfire (for healing)\nBulletin Board (place and write your own text)\nWeapon Box\nWater Dispenser\n\nFarming System\nIn the seed shop, you can purchase seeds and plant them.\nThe following things can be planted:\nApple Trees\nOrange Trees\nHemp\nCacti\n\nPlayer Market\nBuy a market stall to offer your items for sale.\nOther players can purchase these items directly from your stall.\n\nExperience & Level System\nYou can gain experience points through various activities.\nExperience allows you to level up and unlock additional gameplay features.\nRequired XP to level up:\n250 × (your level + 1) + ((your level + 1) × 25)\nWhen leveling up, any new features you unlock will be displayed.\nYour level also determines your rank.\n\nRanks\nThere are 16 total ranks, ranging from Beginner to Legend.\nWith each new rank, you receive the location of a special place.\n\nHelp Menu\nPress F1 to open the in-game Help Menu.\n\nCrafting Menu\nThe crafting menu becomes available in your inventory starting from level 25.\nCrafting recipes are obtained as you progress through the game.\n\nAFK System\nAfter 5 minutes of inactivity, your character will be put into AFK mode automatically.\n\nServer Events & Bonuses\nOne full day on San Andreas Apocalypse lasts 4 real-time hours.\nEvery 15 minutes, a chatbox appears showing server information and granting players a bonus of experience points.\nThe hourly server payday grants players experience points if at least one generator is functioning.\nIf double experience is active, the bonus can be increased to x4 using an experience coupon.\nA script restart takes place every morning.\nNatural events (e.g. earthquakes) can occur and influence gameplay.",
		["Colonies"] = "Colony System\nIt is possible to found your own colony.\n\nColonies unlock additional gameplay mechanics and enable team-based play.\n\nColonies have a level system:\n\nKilling zombies grants experience points for your colony.\nExperience needed for the next level:\n2500 * (current colony level + 1) + ((current colony level + 1) * 25)\nColonies start with 5 player slots and 1 vehicle slot.\nEvery 5 levels, your colony gains +1 player slot and +1 vehicle slot.\nPress F7 to open the Colony Menu, where you can manage members and view all important colony information.\n\nTrash Compactor\nOnce unlocked, members can place items in the Trash Compactor.\nWhen full, it can be compacted, granting rewards for both the member and the colony, and producing a trash block.\n\nWarehouses\nThe higher your colony level, the more warehouses can be purchased.\nWarehouses can store items and vehicles.\n\nZombie Experiments\nConduct experiments on zombies to uncover more about the virus.\n\nDaily & Weekly Tasks\nComplete colony-wide daily and weekly missions for special rewards.\n\nLab Battles\nDestroy and capture enemy laboratories during combat with other colonies.\nLabs are color-coded on the map based on the owning colony.\n\nWarehouse Deliveries\nDeliver supplies to colonies and other locations around the map.\n\nMoney Transport\nFind abandoned money transporters across San Andreas.\nLoad them with cash and deliver them to your colony shelter.\n\nFlag Hunt\nAfter the daily script restart, a random shelter is chosen where a flag will spawn.\nColony members can capture the flag and return it to their own colony shelter for bonuses.\n\nShelter\nShelters can be converted into colony shelters, making them accessible to all colony members.",
		["NPCs"] = "/",
		["Collectibles"] = "F2 – Personal Overview\nUnder F2, you’ll find an overview of:\n\nAchievements\nDocuments\nStatus Effects\nPhotos\nCrafting Recipes\nDiscovered Locations\nKnown Characters\n\nDocuments\nDocuments can be found throughout the game world.\nThey may include:\n\nBackground stories of characters\nTips and tricks\nImportant clues or hints\n\nStatus Effects\nUnlocked status effects can be selected.\nThey are displayed below the player’s name tag and grant specific gameplay advantages.\n\nPhotos & Crafting Recipes\nPhotos and crafting recipes can be found or earned in the world.\n\nKnown Characters\nOnce you’ve met a character, background information about them will be added to your F2 menu.\n\nDiscovered Locations\nWhen you discover a location, its safe zone will be displayed on the map.\n\nCollectibles\nFind and collect items scattered across the world:\n\nHorseshoes\nGTA III Logos\nTiki Statues\nHidden Packages\nThese can be used to shop in the Bonus Shop.\n\nThere are also additional collectibles related to quests, such as:\n\nRusty Chainsaws\nPolice Badges\nBatons\n...and many more.",
		["Changelogs"] = "/",
	}, 
	["RU"] = {
		["Аккаунты и персонажи"] = "После создания аккаунта и персонажа вы начнёте в Зоне 11 — регионе, принадлежащем Dillimore’s Hope, колонии, которая спасла и приютила вас.\nПосле короткого обучения, знакомящего с основными механиками игры, вы можете начать своё приключение и исследовать мир San Andreas.\n\nРеферальная система\nПри регистрации вы можете указать имя рекрутёра.\nРекрутёр получит награды, когда приглашённый игрок достигнет определённого количества часов игры.\nПриглашённых игроков можно посмотреть в меню Self (/me).\n\nНастройки персонажа (F5)\nНажмите F5, чтобы открыть настройки персонажа. Здесь вы можете:\n\nПропустить вступление\nВключить автоматический вход в аккаунт\nВыбрать избранного персонажа для автологина\nСменить пароль\nСменить язык\nСменить точку спавна\nВвести бонус-коды\n\nПравила и санкции\nСуществует свод правил.\nНарушения могут привести к санкциям в отношении аккаунта — временным или постоянным блокировкам в зависимости от тяжести нарушения.\n\nТочки спавна\nВы можете выбрать одну из следующих точек появления:\n\nDillimore (Безопасная зона)\nФерма Безумного Джо\nBlueberry (Безопасная зона)\nХижина Адама Тёрнера (в лесу)\nКлуб Бигфута",

		["Мир игрока"] = "Мир и зоны\nКарта разделена на 24 зоны.\nНекоторые из этих зон требуют Survivor Pass и его улучшений для доступа.\n\nРадиовышки\nВ каждой зоне есть радиовышка, которая открывает ключевые места в этой зоне.\n\nДикая природа и охота\nЖивотные бродят по миру.\nПосле разблокировки охотничьего ножа вы можете убивать животных, чтобы получать:\n\nШкуры\nМясо\nДругие ресурсы\n\nДекоративные NPC\nДекоративных NPC можно нажимать, чтобы получать очки опыта.\n\nИнтерактивные персонажи\nВ мире вы найдёте десятки персонажей.\n\nНажмите пробел, чтобы говорить\nНажмите E, чтобы взаимодействовать\nПросите помощи или дарите подарки\nПодарки повышают уровень дружбы\n\nОткрываемые локации\nСуществуют локации, которые служат безопасными зонами.\nПосле открытия они становятся видны на карте.\n\nУбежища\nПокупайте убежища, чтобы устанавливать новые точки спавна.\n\nМагазины и торговцы\nВ мире есть различные магазины:\n\nМагазин бронежилетов\nБары\nМагазин купонов\nМагазин рыбака\nТочки с едой (хот-доги, автоматы со снеками/напитками, кулеры с водой)\nМагазин предметов\nМагазин ключей\nАвтосалон\nМагазин оружия\nМагазин семян\nМагазин одежды",

		["Зомби"] = "Вне защищённых зон царит хаос. Зомби свободно бродят по улицам — убейте их прежде, чем они убьют вас, и помогите вернуть San Andreas от инфекции.\n\nКаждый убитый зомби награждает вас:\n\nОчками опыта — повышайте уровень и открывайте мощные игровые механики\nДеньгами — тратьте их на необходимое и роскошь\nМозговой массой — редким ресурсом, необходимым для выживания\nИспользуйте деньги и мозговую массу, чтобы приобретать:\n\nОружие\nТранспорт\nКлючи\nУбежища\n...и многое другое!\nОба ресурса крайне важны для выживания и прогресса в этом постапокалиптическом мире.\nВосстанете ли вы и очистите землю — или станете частью орды?",

		["Активности"] = "Профессии\nИщите сокровища и ракушки в море как Охотник за сокровищами.\nСобирайте камни, руды и алмазы как Исследователь пещер.\nСобирайте древесину и перерабатывайте или продавайте её как Лесоруб.\nСобирайте мусор как Уборщик улиц.\nСобирайте мусор в море как Морской уборщик.\nИщите сокровища с металлоискателем как Кладоискатель.\nПомогайте эвакуировать транспорт как Помощник механика.\nУхаживайте за могилами как Смотритель кладбища.\n\nРыбалка\nПосетите рыболовный магазин, найдите подходящее место и попытайте удачу в ловле рыбы и сборе ракушек. Рыбу можно продать, приготовить и съесть или поместить в аквариум, где она будет приносить опыт.\n\nМиссии на транспорте\nНа полицейских участках, в больницах и пожарных частях вы можете найти специальные транспортные средства, которые запускают миссии при посадке. Тип миссии зависит от транспорта — полицейская машина, скорая или пожарная.\nПо всему San Andreas вы будете сталкиваться с различными чрезвычайными ситуациями. Ваша задача — реагировать соответствующим образом: спасать раненых выживших, помогать в экстренных случаях или устранять угрозы.\nВыжившие или цели миссии загружаются в ваш транспорт при взаимодействии.\nЗа каждое успешное действие вы получаете очки опыта.\nЕсли вы покинете миссию, вы всё равно получите частичную награду в зависимости от прогресса.\nПравильное завершение миссий (например, доставка выживших) даёт больше XP, денег и очков навыков.\n\nГнёзда\nНаходятся по всему San Andreas.\nМогут быть уничтожены динамитом.\nПосле уничтожения из них выбегают зомби.\nЗомби из гнёзд дают бонусный опыт.\n\nАирдропы\nПоставки сбрасываются каждые 15 минут в случайных местах после подбора.\nСодержат большое количество предметов.\nОтмечены на карте блипом.\n\nЗаражённые выжившие\nЗаражённые выжившие появляются по всему San Andreas.\nВы можете взять образец крови у живого заражённого с помощью шприца.\nУбийство даёт деньги.\nВремя респавна: 5 минут.\n\nЛут-активности\nБрошенные автомобили\nНаходятся по всей карте.\nЗапускают мини-игру на 15 секунд (кликайте как можно больше предметов).\nБольше кликов = больше лута.\nКулдаун 15 минут (на игрока).\nИндикатор авто: белый = можно лутать, красный = кулдаун.\n\nЛутаемые дома\nТребуют лом для входа.\nМожно лутать 15 минут после открытия.\nКулдаун 30 минут (глобальный).\nШанс появления зомби.\nОбыскивайте интерьеры в поисках предметов.\n\nОбыскиваемые мусорные баки\nНаходятся по всему San Andreas.\nНажмите, чтобы обыскать.\nКулдаун 5 минут (на бак).\nМогут содержать полезные предметы.\nСистема маркеров как у машин.\n\nЛутаемые здания\nПохожи на лутаемые дома.\nТребуют больше ломов.\nОбыскивайте ящики внутри.\nОдин эксклюзивный предмет на тип здания.\nОбыскать всё = бонус.\nШанс появления зомби.\n\nОсобые функции зданий\nПолицейский участок — Комната улик\nУбейте зомби с ключ-картой ИЛИ используйте динамит.\nПолицейский участок — Тюремные камеры\nНайдите ключ-карту или используйте динамит.\nПолицейский участок и пожарная часть\nСодержат документы.\n\nЛутаемые гаражи\nВзрываются динамитом.\nОстаются открытыми 15 минут.\nКулдаун: 30 минут.\nМогут содержать лут или разбираемый транспорт.\n\nБои с боссами\nНажмите здесь для боёв с боссами\n\nСерии лута\nПолучайте бонусные очки навыков за лут нескольких объектов за ограниченное время:\nТип — Лимит времени\nМусорный бак — 1 минута\nДом — 5 минут\nТранспорт — 2 минуты\nЗдание — 15 минут\nНачиная с серии 3 вы получаете бонусные очки навыков.\n\nТипы лутаемых зданий\nТип здания — Эксклюзивный предмет\nСекс-шоп / Стрип-клуб — Дилдо\nЗаправка — Гаечный ключ\nМагазин оружия — Детали оружия\nБольница — Бинт\nПиццерия — Пицца\nМагазин одежды — Ткань\nСупермаркет — Конфеты\nCluckin’ Bell — Куриная ножка\nBurger Shot — Бургер\nПожарная часть — Пожарная каска\nПолицейский участок — Полицейская фуражка\nБар — Вино\nПарикмахерская — Ножницы\nПончиковая — Пончик\nТату-салон — Чернила для тату\n\nАрена стрелков\nНа арене стрелков игроки сражаются друг с другом, управляя Infernus.\nВаш транспорт оснащён оружием, позволяя стрелять во время движения.\nЦель — выбить других игроков с арены тараном и стрельбой.\nПосле уничтожения вы автоматически возрождаетесь без штрафов.\n\nГоночная арена\nГоночная арена позволяет соревноваться с другими игроками в быстрых заездах.\nТрассы узкие и содержат много поворотов.\nКаждое место получает награды в зависимости от позиции.\n\nБоевая арена\nНа боевой арене игроки сражаются в ближнем бою.\nДоступны различные виды оружия и боевые механики.\nАрены компактны и предлагают множество тактических возможностей.\n\nДругие активности\nСуществует множество других активностей, которые помогают прогрессу и добавляют разнообразия.",

		["Бои с боссами"] = "Бигфут\nПосле первого убийства Бигфута и завершения связанного квеста вы получаете доступ к мощным новым возможностям:\n\nКаждые 4 часа вы можете забирать миниган с ограниченным боезапасом.\nВы получаете местоположение Клуба Бигфута, который включает:\nТюрьму Бигфута\nКлубный дом Бигфута\nПосле сдачи 25 голов Бигфута в тюрьме вы получаете ключ от клубного дома.\n\nВнутри клубного дома:\n\nВы открываете точку спавна — Клуб Бигфута.\nВы можете многократно сдавать 25 голов Бигфута за:\nОчки опыта\nКлюч от сейфа\nСлучайный ящик с предметами\nКроме того, пойманный Бигфут пассивно генерирует опыт, пока вы онлайн и состоите в клубе.",

		["Транспорт"] = "Вы можете получить транспорт через магазины, дилеров или как награду за квесты.\nДля покупки или получения транспорта требуется свободный слот.\n\nСлоты транспорта\nВыдаются определёнными NPC.\nДополнительные слоты — через навык.\nСерверный гараж\nПо умолчанию транспорт хранится в серверном гараже.\nДоступен со всех баз колоний.\nТранспорт автоматически загружается при входе.\n\nУправление\nДействие — Клавиша\nДвигатель вкл/выкл — X\nФары вкл/выкл — L\nТранспорту требуется топливо (находится при луте или на заправках).\n\nМеню взаимодействия\nНажмите на транспорт, чтобы:\nПосмотреть информацию\nПерепарковать\nОткрыть багажник\n\nСлучайные автодилеры\nПредлагают уникальный транспорт, недоступный в магазинах:\nCheetah\nMoonbeam\nEsperanto\nBobcat\nBJ Injection\nBanshee\nHotknife\nCaddy\nHermes\nWalton\nBurrito\n\nКастомизация и тюнинг\nТюнинг-гаражи: улучшайте транспорт за детали и деньги.\nМеханик: устанавливает мощные двигатели (большая максимальная скорость).\nPay ‘N Sprays: изменение цвета транспорта.\n\nЧастные гаражи\nВ мире существуют покупаемые гаражи.\nИспользуйте /mg, чтобы открыть/закрыть ворота, если вы владелец.",

		["Системы"] = "Взаимодействие с игроками\nНажмите на другого игрока, чтобы открыть меню взаимодействия.\nЗдесь вы можете передавать предметы и отправлять запросы в друзья.\n\nГруппы\nСоздайте временную группу, чтобы вместе побеждать зомби.\nУбийства зомби членами группы поблизости дают бонусный опыт.\n\nЧат-система\nСообщения с /s [текст] (крик) и /m [текст] (мегафон) имеют увеличенную дальность.\n\nТаблица лидеров\nТоп-10 показывает лучших игроков в различных категориях.\n\nЭкономика\nДеньги можно безопасно хранить в сейфах.\nКаждые 4 часа вы можете бесплатно крутить колесо фортуны и выигрывать ценные предметы, транспорт и многое другое.\nКаждый полный игровой час вы получаете payday с деньгами и опытом в зависимости от уровня. Также вы получаете монету SAA за каждый payday.\n\nСистема оружия\nОружие хранится в инвентаре.\n\nОружие можно получить через:\nМагазины\nКвесты\nКрафт\nСуществуют ящики для хранения оружия.\n\nСуществует навык, увеличивающий количество переносимого оружия.\n\nВ тире вы можете тренировать оружие, чтобы улучшать навыки.\n\nНавыки\nСуществует уровень спринта, который повышается при беге. Чем выше уровень, тем дольше вы можете бежать без остановки.\nВ San Andreas есть базы навыков, предлагающие различные бонусы.\nНавыки стоят очков навыков, получаемых за активности.\nДоступные навыки:\nМедик\nМеханик\nЭксперт по оружию\nЭксперт по транспорту\n\nДобыча руды\nВо время добычи вы можете собирать руды.\nРуды переплавляются в печи в слитки.\nЭти слитки используются для крафта.\n\nРазмещаемые объекты\nРазмещаемые объекты можно купить или скрафтить и установить в мире:\nСейф\nКостёр (для лечения)\nДоска объявлений (можно писать свой текст)\nЯщик для оружия\nДиспенсер воды\n\nСистема фермерства\nВ магазине семян вы можете покупать семена и сажать их.\nМожно посадить:\nЯблони\nАпельсиновые деревья\nКоноплю\nКактусы\n\nРынок игроков\nКупите торговую лавку, чтобы продавать свои предметы.\nДругие игроки могут покупать эти предметы напрямую у вас.\n\nСистема опыта и уровней\nВы можете получать опыт за различные активности.\nОпыт позволяет повышать уровень и открывать новые игровые возможности.\nНеобходимый опыт для повышения уровня:\n250 × (ваш уровень + 1) + ((ваш уровень + 1) × 25)\nПри повышении уровня вам показываются новые открытые возможности.\nВаш уровень также определяет ваш ранг.\n\nРанги\nСуществует 16 рангов — от Новичка до Легенды.\nС каждым новым рангом вы получаете местоположение особого места.\n\nМеню помощи\nНажмите F1, чтобы открыть меню помощи в игре.\n\nМеню крафта\nМеню крафта становится доступным в инвентаре с 25 уровня.\nРецепты крафта получаются по мере прохождения игры.\n\nAFK-система\nПосле 5 минут бездействия ваш персонаж автоматически переводится в режим AFK.\n\nСерверные события и бонусы\nОдин полный день в San Andreas Apocalypse длится 4 реальных часа.\nКаждые 15 минут появляется окно чата с информацией сервера и даёт бонусный опыт.\nЕжечасный payday даёт опыт, если работает хотя бы один генератор.\nПри активном двойном опыте бонус можно увеличить до x4 с помощью купона.\nКаждое утро происходит перезапуск скрипта.\nПриродные события (например, землетрясения) могут влиять на геймплей.",

		["Колонии"] = "Система колоний\nВы можете основать собственную колонию.\n\nКолонии открывают дополнительные игровые механики и позволяют командную игру.\n\nКолонии имеют систему уровней:\n\nУбийства зомби дают опыт колонии.\nОпыт для следующего уровня:\n2500 × (текущий уровень колонии + 1) + ((текущий уровень колонии + 1) × 25)\nКолонии начинают с 5 слотами игроков и 1 слотом транспорта.\nКаждые 5 уровней колония получает +1 слот игрока и +1 слот транспорта.\nНажмите F7, чтобы открыть меню колонии, где можно управлять участниками и смотреть информацию.\n\nПресс для мусора\nПосле разблокировки участники могут помещать предметы в пресс.\nКогда он заполнен, его можно спрессовать, получив награды для участника и колонии и создав блок мусора.\n\nСклады\nЧем выше уровень колонии, тем больше складов можно купить.\nСклады хранят предметы и транспорт.\n\nЭксперименты над зомби\nПроводите эксперименты над зомби, чтобы узнать больше о вирусе.\n\nЕжедневные и еженедельные задания\nВыполняйте задания колонии и получайте особые награды.\n\nБои за лаборатории\nУничтожайте и захватывайте вражеские лаборатории в боях с другими колониями.\nЛаборатории отмечены на карте цветом владельца.\n\nПоставки на склады\nДоставляйте припасы колониям и в другие точки карты.\n\nПеревозка денег\nНаходите брошенные инкассаторские машины в San Andreas.\nЗагружайте их деньгами и доставляйте в убежище колонии.\n\nОхота за флагом\nПосле ежедневного перезапуска скрипта выбирается случайное убежище, где появляется флаг.\nЧлены колонии могут захватить флаг и вернуть его в своё убежище ради бонусов.\n\nУбежища\nУбежища можно превратить в убежища колонии, сделав их доступными для всех участников.",

		["NPC"] = "/",

		["Коллекционные предметы"] = "F2 — Личный обзор\nВ F2 вы найдёте обзор:\n\nДостижений\nДокументов\nСтатус-эффектов\nФотографий\nРецептов крафта\nОткрытых локаций\nИзвестных персонажей\n\nДокументы\nДокументы можно найти в мире игры.\nОни могут содержать:\n\nПредыстории персонажей\nСоветы и подсказки\nВажные намёки\n\nСтатус-эффекты\nРазблокированные статус-эффекты можно выбрать.\nОни отображаются под ником игрока и дают преимущества.\n\nФото и рецепты крафта\nФото и рецепты можно найти или заработать.\n\nИзвестные персонажи\nПосле знакомства с персонажем информация о нём добавляется в меню F2.\n\nОткрытые локации\nПосле открытия локации её безопасная зона отображается на карте.\n\nКоллекционные предметы\nНаходите и собирайте предметы в мире:\n\nПодковы\nЛоготипы GTA III\nСтатуи Тики\nСкрытые пакеты\nИх можно использовать в Бонус-магазине.\n\nТакже существуют дополнительные коллекционные предметы, связанные с квестами, такие как:\n\nРжавые бензопилы\nПолицейские значки\nДубинки\n...и многое другое.",

		["Список изменений"] = "/",
	},
}

bindKey("f1", "down", function()
    if (Helpmenu.Open == true) then
        closeWindow()
        Helpmenu.Open = false
    else
        if (isCharacterLoggedIn() and isWindowOpen()) then
            local image
            GUIEditor.window[1] = guiCreateWindow(426, 149, 741, 426, "Community Board", false)

            GUIEditor.tabpanel[1] = guiCreateTabPanel(10, 25, 721, 391, false, GUIEditor.window[1])
            GUIEditor.tab[1] = guiCreateTab(getText("CHelpmenu4"), GUIEditor.tabpanel[1])

            if (HalloweenEvent == true) then
                image = "SAApocalypse_Halloween"
            else
                image = "SAApocalypse"
            end

            GUIEditor.staticimage[1] = guiCreateStaticImage(228, 10, 268, 53, "Files/Images/"..image..".png", false, GUIEditor.tab[1])
            GUIEditor.label[1] = guiCreateLabel(10, 73, 701, 256, getText("CHelpmenu5"), false, GUIEditor.tab[1])
            guiSetFont(GUIEditor.label[1], "default-bold-small")
            guiLabelSetHorizontalAlign(GUIEditor.label[1], "left", true)
            GUIEditor.label[2] = guiCreateLabel(10, 339, 701, 18, "San Andreas Apocalypse v.1.0.8 - Last Update: 1 March 2026", false, GUIEditor.tab[1])
            guiSetFont(GUIEditor.label[2], "default-small")
            guiLabelSetVerticalAlign(GUIEditor.label[2], "center")

            GUIEditor.tab[5] = guiCreateTab(getText("CHelpmenu1"), GUIEditor.tabpanel[1])

            GUIEditor.gridlist[4] = guiCreateGridList(10, 10, 206, 347, false, GUIEditor.tab[5])
            HelpmenuCategory = guiGridListAddColumn(GUIEditor.gridlist[4], getText("CHelpmenu3"), 0.9)

            -- Scrollpanel & Labels
            GUIEditor.scrollpane = guiCreateScrollPane(226, 50, 485, 307, false, GUIEditor.tab[5])
            GUIEditor.dynamicLabels = {} -- Liste zum Speichern dynamisch erzeugter Labels

            GUIEditor.label[13] = guiCreateLabel(226, 10, 485, 30, getText("CHelpmenu2"), false, GUIEditor.tab[5])
            guiSetFont(GUIEditor.label[13], "default-bold-small")
            guiLabelSetHorizontalAlign(GUIEditor.label[13], "left", true)

            Helpmenu.Open = true
            setWindowData()

            addEventHandler("onClientGUIClick", GUIEditor.gridlist[4], function()
				local clicked = guiGridListGetItemText(GUIEditor.gridlist[4], guiGridListGetSelectedItem(GUIEditor.gridlist[4]), 1)
				if clicked ~= "" then
					guiSetText(GUIEditor.label[13], clicked)

					local text = Texts[apocalypseGetElementData(localPlayer, "language") or "EN"][clicked] or ""

					if GUIEditor.dynamicLabels then
						for _, lbl in ipairs(GUIEditor.dynamicLabels) do
							if isElement(lbl) then
								destroyElement(lbl)
							end
						end
						GUIEditor.dynamicLabels = {}
					end

					local y = 0
					local lineHeight = 15
					local extraSpacing = lineHeight / 2

					for line in text:gmatch("[^\n]*") do
						if line ~= nil then
							local lbl = guiCreateLabel(0, y, 465, lineHeight, line, false, GUIEditor.scrollpane)
							guiSetFont(lbl, "default-bold-small")
							guiLabelSetHorizontalAlign(lbl, "left", true)
							guiLabelSetVerticalAlign(lbl, "top")
							table.insert(GUIEditor.dynamicLabels, lbl)
							y = y + lineHeight

							if line == "" then
								--y = y + extraSpacing
								y = y
							end
						end
					end
				end
			end, false)

            triggerServerEvent("Helpmenu.getDatas", localPlayer)
        end
    end
end)

addEvent("Helpmenu.updateDatas", true)
addEventHandler("Helpmenu.updateDatas", root, function(Datas)
    for _, v in pairs(Datas) do
        local row = guiGridListAddRow(GUIEditor.gridlist[4])
        guiGridListSetItemText(GUIEditor.gridlist[4], row, HelpmenuCategory, v, false, false)
    end
end)

function Helpmenu.createHelpMarker(ID, x, y, z, int, dim)
    if (not isElement(Helpmenu.Helpmarker[ID])) then
        Helpmenu.Helpmarker[ID] = createMarker(x, y, z, "corona", 1, 0, 255, 0, 50)
        setElementInterior(Helpmenu.Helpmarker[ID], int)
        setElementDimension(Helpmenu.Helpmarker[ID], dim)
    end
end
addEvent("Helpmenu.createHelpMarker", true)
addEventHandler("Helpmenu.createHelpMarker", root, Helpmenu.createHelpMarker)

function Helpmenu.destroyHelpMarker(ID)
    local ID = tonumber(ID)
    if (isElement(Helpmenu.Helpmarker[ID])) then
        destroyElement(Helpmenu.Helpmarker[ID])
    end
end
addEvent("Helpmenu.destroyHelpMarker", true)
addEventHandler("Helpmenu.destroyHelpMarker", root, Helpmenu.destroyHelpMarker)
